#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cmpch(const void *a, const void *b) {
    return (int)*(const unsigned char *)a - (int)*(const unsigned char *)b;
}

/*
 * Ideia: as posicoes normais sao fixas, entao a ordem lexicografica das
 * senhas equivale a ordem lexicografica das escolhas (c1..cM) dos indices
 * nas listas ordenadas. Isso e um sistema de numeracao de base mista:
 * o indice (P-1) codifica as escolhas, da cifra menos significativa
 * (ultima letra borrada) para a mais significativa (primeira letra borrada).
 */
int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    static char senha[512];
    if (scanf("%511s", senha) != 1) return 0;

    static char *dict[512];  /* letras ordenadas (e sem repeticao) de cada palavra */
    static int dcnt[512];    /* quantidade de opcoes por posicao borrada */
    static int pos[512];     /* posicoes borradas, da esquerda para a direita */

    int m = 0;
    for (int i = 0; i < N && m < M; i++)
        if (senha[i] == '#') pos[m++] = i;

    char word[64];
    for (int i = 0; i < M; i++) {
        if (scanf("%63s", word) != 1) return 0;
        qsort(word, (size_t)K, 1, cmpch);
        int d = 0;
        for (int j = 0; j < K; j++)          /* remove duplicatas, mantem ordem */
            if (j == 0 || word[j] != word[j - 1])
                word[d++] = word[j];
        dcnt[i] = d;
        dict[i] = (char *)malloc((size_t)d + 1);
        memcpy(dict[i], word, (size_t)d);
        dict[i][d] = '\0';
    }

    long long P;
    if (scanf("%lld", &P) != 1) return 0;

    long long X = P - 1;                     /* indice 0-based na lista ordenada */
    for (int i = M - 1; i >= 0; i--) {       /* da ultima para a primeira borrada */
        int c = (int)(X % dcnt[i]);
        X /= dcnt[i];
        senha[pos[i]] = dict[i][c];
    }

    senha[N] = '\0';
    fputs(senha, stdout);
    fputc('\n', stdout);
    return 0;
}
